insert into public.quotes (id, lang, text, translation, translation_by, author, author_alt, work, year, source_url, source_note, verified_on) values
('en-thoreau-walden-castles', 'en', 'If you have built castles in the air, your work need not be lost; that is where they should be. Now put the foundations under them.', 'إن كنتَ قد بنيتَ قصورًا في الهواء، فعملك لم يضِع؛ فهناك مكانها. والآن ضع الأساسات تحتها.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://www.literaturepage.com/read/walden-243.html', 'Public domain.', '2026-11-03'),
('en-tennyson-ulysses-strive', 'en', 'To strive, to seek, to find, and not to yield.', 'أن نجاهد، وأن نسعى، وأن نجد، وألّا نستسلم.', 'app', 'Alfred, Lord Tennyson', 'ألفريد تينيسون', 'Ulysses (final line)', '1842', 'https://rpo.library.utoronto.ca/poems/ulysses', 'Public domain. The source prints the line in lower case as the end of a sentence; capitalized here as a standalone excerpt.', '2026-11-03'),
('en-emerson-self-reliance-trust', 'en', 'Trust thyself: every heart vibrates to that iron string.', 'ثِق بنفسك: كل قلبٍ يهتز لذلك الوتر الحديدي.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance (Essays: First Series)', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain.', '2026-11-03'),
('en-shakespeare-measure-doubts', 'en', 'Our doubts are traitors, / And make us lose the good we oft might win, / By fearing to attempt.', 'شكوكنا خونة، تُضيّع علينا الخير الذي كان يمكن أن نكسبه، لأننا نخاف أن نحاول.', 'app', 'William Shakespeare', 'وليم شكسبير', 'Measure for Measure, Act 1, Scene 4 (Lucio)', 'c. 1603–1604', 'https://absoluteshakespeare.com/plays/measure_for_measure/a1s4.htm', 'Public domain. Punctuation follows the linked edition; other editions omit the comma after “win”.', '2026-11-03'),
('ar-mutanabbi-ghamarta', 'ar', 'إِذا غامَرتَ في شَرَفٍ مَرومٍ ... فَلا تَقنَع بِما دونَ النُجومِ', 'If you venture after a coveted honor, do not settle for anything below the stars.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «إذا غامرت في شرف مروم» — الديوان', 'القرن الرابع الهجري / 10th century', 'https://www.aldiwan.net/poem10566.html', 'ملكية عامة. النص كما في صفحة الديوان المرتبطة.', '2026-11-03'),
('ar-shabbi-iradat-al-hayat-jibal', 'ar', 'ومن لا يحبُّ صُعودَ الجبالِ ... يَعِشْ أبَدَ الدَّهرِ بَيْنَ الحُفَرْ', 'Whoever does not love climbing mountains will live forever among the pits.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة (توفي الشاعر 1934). تشتهر رواية «ومن يتهيّب صعود الجبال»؛ المعروض هنا هو نص المصدر المرتبط.', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-000', 'ar', 'وَمَن يَكُ ذا فَضلٍ فَيَبخَل بِفَضلِهِ ... عَلى قَومِهِ يُستَغنَ عَنهُ وَيُذمَمِ', 'Whoever has a gift and withholds it from his people will be done without, and blamed.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-001', 'ar', 'وَمَن يَجعَلِ المَعروفَ مِن دونِ عِرضِهِ ... يَفِرهُ وَمَن لا يَتَّقِ الشَتمَ يُشتَمِ', 'Whoever uses generosity to shield his honor keeps it whole; whoever does not guard against insult will be insulted.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-002', 'ar', 'وَمَن هابَ أَسبابَ المَنِيَّةِ يَلقَها ... وَلَو رامَ أَسبابَ السَماءِ بِسُلَّمِ', 'Whoever fears the causes of death will meet them, even if he climbs a ladder to the sky.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-003', 'ar', 'وَمَن يوفِ لا يُذمَم وَمَن يُفضِ قَلبُهُ ... إِلى مُطمَئِنِّ البِرِّ لا يَتَجَمجَمِ', 'Whoever keeps his word is not blamed, and a heart that rests in goodness does not hesitate.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-004', 'ar', 'وَمَن يَغتَرِب يَحسِب عَدُوّاً صَديقَهُ ... وَمَن لا يُكَرِّم نَفسَهُ لا يُكَرَّمِ', 'Far from home, you may take an enemy for a friend; and whoever does not honor himself will not be honored.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-005', 'ar', 'وَمَهما تَكُن عِندَ اِمرِئٍ مِن خَليقَةٍ ... وَإِن خالَها تَخفى عَلى الناسِ تُعلَمِ', 'Whatever trait a person has, even if he thinks it hidden from people, will become known.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-006', 'ar', 'وَمَن لا يَزَل يَستَحمِلُ الناسَ نَفسَهُ ... وَلا يُغنِها يَوماً مِنَ الدَهرِ يُسأَمِ', 'Whoever keeps loading himself onto others and never makes himself independent will in time grow tiresome to them.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-007', 'ar', 'وَأَعلَمُ عِلمَ اليَومِ وَالأَمسِ قَبلَهُ ... وَلَكِنَّني عَن عِلمِ ما في غَدٍ عَمي', 'I know what today holds, and yesterday before it, but I am blind to what tomorrow holds.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-zuhayr-ibn-abi-sulma-008', 'ar', 'فَلا تَكتُمُنَّ اللَهَ ما في نُفوسِكُم ... لِيَخفى وَمَهما يُكتَمِ اللَهُ يَعلَمِ', 'Do not try to hide from God what is in your hearts; whatever is hidden from Him, God knows.', 'app', 'زهير بن أبي سلمى', 'Zuhayr ibn Abi Sulma', 'المعلقة «أمن أم أوفى دمنة لم تكلم»', 'ما قبل الإسلام / 6th century', 'https://www.aldiwan.net/poem25065.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-009', 'ar', 'عَلى قَدرِ أَهلِ العَزمِ تَأتي العَزائِمُ ... وَتَأتي عَلى قَدرِ الكِرامِ المَكارِمُ', 'Resolve comes in the measure of the resolute, and noble deeds in the measure of the noble.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «على قدر أهل العزم تأتي العزائم»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/ala-qdr-ahl-alazm-bxck86', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-010', 'ar', 'وَتَعظُمُ في عَينِ الصَغيرِ صِغارُها ... وَتَصغُرُ في عَينِ العَظيمِ العَظائِمُ', 'Small things look great in small eyes, and great things look small in great eyes.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «على قدر أهل العزم تأتي العزائم»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/ala-qdr-ahl-alazm-bxck86', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-011', 'ar', 'إِذا كانَ ما تَنويهِ فِعلاً مُضارِعاً ... مَضى قَبلَ أَن تُلقى عَلَيهِ الجَوازِمُ', 'When what you intend is a deed in progress, it is done before anything can cut it short.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «على قدر أهل العزم تأتي العزائم»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/ala-qdr-ahl-alazm-bxck86', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-012', 'ar', 'إِذا تَرَحَّلتَ عَن قَومٍ وَقَد قَدَروا ... أَن لا تُفارِقَهُم فَالراحِلونَ هُمُ', 'If you leave people who could have kept you from leaving, they are the ones who have truly left.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «واحر قلباه ممن قلبه شبم»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/wahr-qlbah-mmn-qlbh-44399h', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-013', 'ar', 'شَرُّ البِلادِ مَكانٌ لا صَديقَ بِهِ ... وَشَرُّ ما يَكسِبُ الإِنسانُ ما يَصِمُ', 'The worst land is a place with no friend in it, and the worst gain is one that brings disgrace.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «واحر قلباه ممن قلبه شبم»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/wahr-qlbah-mmn-qlbh-44399h', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-014', 'ar', 'إِذا نَظَرتَ نُيوبَ اللَيثِ بارِزَةً ... فَلا تَظُنَّنَّ أَنَّ اللَيثَ مُبتَسِمُ', 'When you see the lion''s fangs bared, do not think the lion is smiling.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «واحر قلباه ممن قلبه شبم»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/wahr-qlbah-mmn-qlbh-44399h', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-015', 'ar', 'وَما اِنتِفاعُ أَخي الدُنيا بِناظِرِهِ ... إِذا اِستَوَت عِندَهُ الأَنوارُ وَالظُلَمُ', 'What use are a man''s eyes to him if light and darkness look the same to him?', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «واحر قلباه ممن قلبه شبم»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/wahr-qlbah-mmn-qlbh-44399h', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-016', 'ar', 'إِذا الشَّعْبُ يوماً أرادَ الحياةَ ... فلا بُدَّ أنْ يَسْتَجيبَ القدرْ', 'If a people one day wills to live, fate must answer.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-017', 'ar', 'ولا بُدَّ للَّيْلِ أنْ ينجلي ... ولا بُدَّ للقيدِ أن يَنْكَسِرْ', 'The night must clear, and the chain must break.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-018', 'ar', 'ومَن لم يعانقْهُ شَوْقُ الحياةِ ... تَبَخَّرَ في جَوِّها واندَثَرْ', 'Whoever is not embraced by a longing for life evaporates into its air and vanishes.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-019', 'ar', 'إِذا مَا طَمحْتُ إلى غايةٍ ... رَكِبتُ المنى ونَسيتُ الحَذرْ', 'When I aspire to a goal, I ride my hopes and forget caution.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-020', 'ar', 'ولم أتجنَّبْ وُعورَ الشِّعابِ ... ولا كُبَّةَ اللَّهَبِ المُستَعِرْ', 'I did not avoid the rough mountain paths, nor the blazing mass of flame.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-021', 'ar', 'أُباركُ في النَّاسِ أهلَ الطُّموحِ ... ومَن يَسْتَلِذُّ ركوبَ الخطرْ', 'I bless the ambitious among people, and those who enjoy facing risk.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-022', 'ar', 'وأُعْلِنَ في الكونِ أنَّ الطّموحَ ... لهيبُ الحَيَاةِ ورُوحُ الظَّفَرْ', 'And I declare to the world that ambition is the flame of life and the spirit of victory.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-023', 'ar', 'إِذا طَمَحَتْ للحَياةِ النُّفوسُ ... فلا بُدَّ أنْ يستجيبَ القَدَرْ', 'When souls aspire to life, fate must answer.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-qasim-al-shabbi-024', 'ar', 'ومن تَعْبُدُ النُّورَ أَحلامهُ ... يُبارِكُهُ النُّورُ أَنَّى ظَهَرْ', 'Whoever dreams in devotion to the light, the light blesses wherever it appears.', 'app', 'أبو القاسم الشابي', 'Abu al-Qasim al-Shabbi', 'قصيدة «إرادة الحياة» — ديوان «أغاني الحياة»', '1933', 'https://adabworld.com/poems/idha-alshab-ywma-arad-alhyah-aqlyegrq', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ibn-al-wardi-025', 'ar', 'اطلبِ العلمَ ولا تكسلْ فما ... أبعدَ الخيرَ على أهلِ الكسلْ', 'Seek knowledge and do not be lazy; how far good things are from the lazy!', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-026', 'ar', 'واهجرِ النومَ وحصِّلْهُ فَمَنْ ... يعرفِ المطلوبَ يحقرْ ما بذلْ', 'Give up sleep and gain it; whoever knows what he seeks thinks little of what he spends.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-027', 'ar', 'لا تقلْ قدْ ذهبَتْ أربابُهُ ... كلُّ مَنْ سارَ على الدربِ وصلْ', 'Do not say its masters are gone; whoever walks the road arrives.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-028', 'ar', 'في ازديادِ العلمِ إرغامُ العِدى ... وجمالُ العلمِ يا صاحِ العملْ', 'Growing in knowledge humbles your rivals, and the beauty of knowledge, my friend, is action.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-029', 'ar', 'لا تقلْ أصلي وفصلي أبدا ... إنما أصلُ الفتى ما قدْ حصلْ', 'Never say ''my origin, my lineage''; a man''s true origin is what he has achieved.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-030', 'ar', 'قدْ يسودُ المرءُ منْ غيرِ أبٍ ... وبحسنِ السبكِ قَدْ يُنْفى الزغلْ', 'A man may lead without a famous father; good refining removes the impurity.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-031', 'ar', 'قيمةُ الإنسانِ ما يحسِنُهُ ... أكثرَ الإنسانُ منهُ أوْ أقلْ', 'A person''s worth is what he does well, whether he does much of it or little.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-032', 'ar', 'وادّرعْ جداً وكداً واجتنبْ ... صحبةَ الحمقى وأربابِ البخلْ', 'Put on the armor of effort and toil, and avoid the company of fools and misers.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-033', 'ar', 'قصِّرِ الآمالَ في الدنيا تفزْ ... فدليلُ العقلِ تقصيرُ الأملْ', 'Keep your worldly hopes short and you will win; short hope is the sign of reason.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-ibn-al-wardi-034', 'ar', 'ليسَ ما يحوي الفتى عَنْ عزمِهِ ... لا ولا ما فاتَ يوماً بالكسلْ', 'What a man gains does not come apart from his resolve, and what he loses is not lost by laziness alone.', 'app', 'ابن الوردي', 'Ibn al-Wardi', '«لامية ابن الوردي» (اعتزل ذكر الأغاني والغزل)', 'القرن الثامن الهجري / 14th century', 'https://adabworld.com/poems/aatzl-dhkr-alaghany-walghzl-88vc3o', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-al-tughra-i-035', 'ar', 'قد رشَّحوك لأمرٍ إنْ فطِنتَ لهُ ... فاربأْ بنفسكَ أن ترعى مع الهَمَلِ', 'They have put you forward for a great matter, if you grasp it; so raise yourself above grazing with the herd.', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-tughra-i-036', 'ar', 'أُريدُ بسطةَ كَفٍ أستعينُ بها ... على قضاءِ حُقوقٍ للعُلَى قِبَلي', 'I want an open hand, to help me pay the debts I owe to high ambition.', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-tughra-i-037', 'ar', 'رضَى الذليلِ بخفضِ العيشِ يخفضُه ... والعِزُّ عندَ رسيمِ الأينُقِ الذُلُلِ', 'The lowly man''s content with a low life keeps him low; honor lies in the hard ride of tireless camels.', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-tughra-i-038', 'ar', 'وعادةُ النصلِ أن يُزْهَى بجوهرِه ... وليس يعملُ إلّا في يدَيْ بَطَلِ', 'A blade may pride itself on its steel, yet it works only in a hero''s hands.', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-tughra-i-039', 'ar', 'أعلِّلُ النفس بالآمالِ أرقُبُها ... ما أضيقَ العيشَ لولا فسحةُ الأمَلِ', 'I comfort my soul with hopes I watch for; how narrow life would be without the room that hope gives!', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-tughra-i-040', 'ar', 'حبُّ السلامةِ يُثْني همَّ صاحِبه ... عن المعالي ويُغرِي المرءَ بالكَسلِ', 'Love of safety turns a man''s ambition from high things and tempts him to laziness.', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-tughra-i-041', 'ar', 'فاصبرْ لها غيرَ محتالٍ ولا ضَجِرٍ ... في حادثِ الدهرِ ما يُغني عن الحِيَلِ', 'Endure it without scheming or complaint; in the blows of time, patience serves better than tricks.', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-tughra-i-042', 'ar', 'غالى بنفسيَ عِرفاني بقيمتِها ... فصُنْتُها عن رخيصِ القَدْرِ مبتَذَلِ', 'Knowing my own worth made me value myself, so I kept myself from what is cheap and common.', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-tughra-i-043', 'ar', 'لم أرتضِ العيشَ والأيامُ مقبلةٌ ... فكيف أرضَى وقد ولَّتْ على عَجَلِ', 'I was not content with life when the days were coming toward me; how could I be, now that they hurry away?', 'app', 'الطغرائي', 'al-Tughra''i', '«لامية العجم» (أصالة الرأي صانتني)', 'القرن الخامس الهجري / 11th–12th century', 'https://adabworld.com/poems/asala-alray-santny-lamya-wi50vt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-044', 'ar', 'إِذا أَنتَ أَكرَمتَ الكَريمَ مَلَكتَهُ ... وَإِن أَنتَ أَكرَمتَ اللَئيمَ تَمَرَّدا', 'If you honor a noble man, you win him; if you honor a base man, he rebels.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «لكل امرئ من دهره ما تعودا»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/%D9%82%D8%B5%D9%8A%D8%AF%D8%A9-%D9%84%D9%83%D9%84-%D8%A7%D9%85%D8%B1%D8%A6-%D9%85%D9%86-%D8%AF%D9%87%D8%B1%D9%87-%D9%85%D8%A7-%D8%AA%D8%B9%D9%88%D8%AF%D8%A7/', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-045', 'ar', 'وَوَضعُ النَدى في مَوضِعِ السَيفِ بِالعُلا ... مُضِرٌّ كَوَضعِ السَيفِ في مَوضِعِ النَدى', 'Giving gifts where the sword is needed harms one''s standing, just as using the sword where gifts are needed.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «لكل امرئ من دهره ما تعودا»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/%D9%82%D8%B5%D9%8A%D8%AF%D8%A9-%D9%84%D9%83%D9%84-%D8%A7%D9%85%D8%B1%D8%A6-%D9%85%D9%86-%D8%AF%D9%87%D8%B1%D9%87-%D9%85%D8%A7-%D8%AA%D8%B9%D9%88%D8%AF%D8%A7/', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-047', 'ar', 'وَإِذا كانَتِ النُفوسُ كِباراً ... تَعِبَت في مُرادِها الأَجسامُ', 'When souls are great, the bodies tire in serving their aims.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «أين أزمعت أيهذا الهمام»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/ayn-azmat-ayhdha-alhmam-n40stm', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-tayyib-al-mutanab-048', 'ar', 'فَكَثيرٌ مِنَ الشُجاعِ التَوَقّي ... وَكَثيرٌ مِنَ البَليغِ السَلامُ', 'Often a brave man''s courage is caution, and often an eloquent man''s speech is a simple greeting.', 'app', 'أبو الطيب المتنبي', 'Abu al-Tayyib al-Mutanabbi', 'قصيدة «أين أزمعت أيهذا الهمام»', 'القرن الرابع الهجري / 10th century', 'https://adabworld.com/poems/ayn-azmat-ayhdha-alhmam-n40stm', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-049', 'ar', 'دَعِ الأَيّامَ تَفعَلُ ما تَشاءُ ... وَطِب نَفساً إِذا حَكَمَ القَضاءُ', 'Let the days do what they will, and be at peace when fate decides.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-050', 'ar', 'وَلا تَجزَع لِحادِثَةِ اللَيالي ... فَما لِحَوادِثِ الدُنيا بَقاءُ', 'Do not despair at the misfortunes of the nights; nothing that happens in this world lasts.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-051', 'ar', 'وَكُن رَجُلاً عَلى الأَهوالِ جَلداً ... وَشيمَتُكَ السَماحَةُ وَالوَفاءُ', 'Be a man who stands firm in hardship, whose nature is generosity and loyalty.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-052', 'ar', 'تَسَتَّر بِالسَخاءِ فَكُلُّ عَيبٍ ... يُغَطّيهِ كَما قيلَ السَخاءُ', 'Cover yourself with generosity; generosity, as they say, covers every fault.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-053', 'ar', 'وَلا تَرجُ السَماحَةَ مِن بَخيلٍ ... فَما في النارِ لِلظَمآنِ ماءُ', 'Do not hope for generosity from a miser; there is no water in fire for the thirsty.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-054', 'ar', 'وَرِزقُكَ لَيسَ يُنقِصُهُ التَأَنّي ... وَلَيسَ يَزيدُ في الرِزقِ العَناءُ', 'Patience does not reduce your provision, and anxious strain does not increase it.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-055', 'ar', 'وَلا حُزنٌ يَدومُ وَلا سُرورٌ ... وَلا بُؤسٌ عَلَيكَ وَلا رَخاءُ', 'No sadness lasts, nor joy; no hardship stays with you, nor ease.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-056', 'ar', 'إِذا ما كُنتَ ذا قَلبٍ قَنوعٍ ... فَأَنتَ وَمالِكُ الدُنيا سَواءُ', 'If you have a contented heart, you and the owner of the world are equal.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-057', 'ar', 'وَأَرضُ اللَهِ واسِعَةٌ وَلَكِن ... إِذا نَزَلَ القَضا ضاقَ الفَضاءُ', 'God''s earth is wide, but when fate descends, the open space grows narrow.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «دع الأيام تفعل ما تشاء» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/da-alayam-tfal-ma-8kz1em', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-058', 'ar', 'ما في المَقامِ لِذي عَقلٍ وَذي أَدَبِ ... مِن راحَةٍ فَدَعِ الأَوطانَ وَاِغتَرِبِ', 'For a person of mind and learning there is no rest in staying put; leave home and travel.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «ما في المقام لذي عقل وذي أدب» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/ma-fy-almqam-ldhy-516g06', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-059', 'ar', 'سافِر تَجِد عِوَضاً عَمَّن تُفارِقُهُ ... وَاِنصَب فَإِنَّ لَذيذَ العَيشِ في النَصَبِ', 'Travel, and you will find a replacement for whom you leave; and toil, for the sweetness of life lies in toil.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «ما في المقام لذي عقل وذي أدب» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/ma-fy-almqam-ldhy-516g06', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-060', 'ar', 'إِنّي رَأَيتُ وُقوفَ الماءِ يُفسِدُهُ ... إِن ساحَ طابَ وَإِن لَم يَجرِ لَم يَطِبِ', 'I have seen that standing water spoils: if it flows it is sweet, and if it does not run it is not.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «ما في المقام لذي عقل وذي أدب» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/ma-fy-almqam-ldhy-516g06', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-061', 'ar', 'وَالأُسدُ لَولا فِراقُ الأَرضِ مااِفتَرَسَت ... وَالسَهمُ لَولا فِراقُ القَوسِ لَم يُصِبِ', 'Lions would not hunt if they never left their ground, and an arrow would not hit if it never left the bow.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «ما في المقام لذي عقل وذي أدب» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/ma-fy-almqam-ldhy-516g06', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-062', 'ar', 'وَالشَمسُ لَو وَقَفَت في الفُلكِ دائِمَةً ... لَمَلَّها الناسُ مِن عُجمٍ وَمِن عَرَبِ', 'If the sun stood still in the sky forever, all people, Arab and non-Arab, would grow tired of it.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «ما في المقام لذي عقل وذي أدب» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/ma-fy-almqam-ldhy-516g06', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-063', 'ar', 'وَالتِبرُ كَالتُربِ مُلقىً في أَماكِنِهِ ... وَالعودُ في أَرضِهِ نَوعٌ مِنَ الحَطَبِ', 'Gold dust lies like plain dirt where it is found, and aloes wood in its own land is just a kind of firewood.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', 'قصيدة «ما في المقام لذي عقل وذي أدب» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/ma-fy-almqam-ldhy-516g06', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-ahmed-shawqi-064', 'ar', 'وَما نَيلُ المَطالِبِ بِالتَمَنّي ... وَلَكِن تُؤخَذُ الدُنيا غِلابا', 'Goals are not reached by wishing; the world is taken by striving.', 'app', 'أحمد شوقي', 'Ahmed Shawqi', 'قصيدة «سلوا قلبي» (الشوقيات)', '1914', 'https://adabworld.com/poems/slw-qlby-ghdah-sla-wthaba-sruwg90j', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ahmed-shawqi-065', 'ar', 'وَما اِستَعصى عَلى قَومٍ مَنالٌ ... إِذا الإِقدامُ كانَ لَهُم رِكابا', 'No goal is out of reach for a people when boldness is their mount.', 'app', 'أحمد شوقي', 'Ahmed Shawqi', 'قصيدة «سلوا قلبي» (الشوقيات)', '1914', 'https://adabworld.com/poems/slw-qlby-ghdah-sla-wthaba-sruwg90j', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ahmed-shawqi-066', 'ar', 'فَعَلِّم ما اِستَطَعتَ لَعَلَّ جيلاً ... سَيَأتي يُحدِثُ العَجَبَ العُجابا', 'Teach what you can; perhaps a generation will come that does wonders.', 'app', 'أحمد شوقي', 'Ahmed Shawqi', 'قصيدة «سلوا قلبي» (الشوقيات)', '1914', 'https://adabworld.com/poems/slw-qlby-ghdah-sla-wthaba-sruwg90j', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ahmed-shawqi-067', 'ar', 'فَإِن قُرِنَت مَكارِمُها بِعِلمٍ ... تَذَلَّلَتِ العُلا بِهِما صِعابا', 'When noble character is joined with knowledge, the heights become easy to climb.', 'app', 'أحمد شوقي', 'Ahmed Shawqi', 'قصيدة «سلوا قلبي» (الشوقيات)', '1914', 'https://adabworld.com/poems/slw-qlby-ghdah-sla-wthaba-sruwg90j', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ahmed-shawqi-068', 'ar', 'فَما حَرَمَ المُجِدَّ جَنى يَدَيهِ ... وَلا نَسِيَ الشَقِيَّ وَلا المُصابا', 'The hard worker is never denied the fruit of his hands.', 'app', 'أحمد شوقي', 'Ahmed Shawqi', 'قصيدة «سلوا قلبي» (الشوقيات)', '1914', 'https://adabworld.com/poems/slw-qlby-ghdah-sla-wthaba-sruwg90j', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ahmed-shawqi-069', 'ar', 'وَلا تُرهِق شَبابَ الحَيِّ يَأساً ... فَإِنَّ اليَأسَ يَختَرِمُ الشَبابا', 'Do not burden the young with despair, for despair destroys youth.', 'app', 'أحمد شوقي', 'Ahmed Shawqi', 'قصيدة «سلوا قلبي» (الشوقيات)', '1914', 'https://adabworld.com/poems/slw-qlby-ghdah-sla-wthaba-sruwg90j', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ahmed-shawqi-070', 'ar', 'وَأَنَّ البِرَّ خَيرٌ في حَياةٍ ... وَأَبقى بَعدَ صاحِبِهِ ثَوابا', 'Doing good is best in life, and its reward outlasts the one who did it.', 'app', 'أحمد شوقي', 'Ahmed Shawqi', 'قصيدة «سلوا قلبي» (الشوقيات)', '1914', 'https://adabworld.com/poems/slw-qlby-ghdah-sla-wthaba-sruwg90j', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-fath-al-busti-071', 'ar', 'أحسِنْ إلى النّاسِ تَستَعبِدْ قُلوبَهُمُ ... فطالَما استبَعدَ الإنسانَ إحسانُ', 'Be good to people and you will win their hearts; kindness has long won people over.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-072', 'ar', 'وكُنْ على الدَّهر مِعواناً لذي أمَلٍ ... يَرجو نَداكَ فإنَّ الحُرَّ مِعْوانُ', 'In hard times, be a helper to anyone who hopes for your generosity, for the free man is a helper.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-073', 'ar', 'والرَّوضُ يَزدانُ بالنُّوَّارِ فاغِمةً ... والحُرُّ بالأصلِ والإحسانِ يَزْدانُ', 'A garden is adorned by its blossoms, and a free man by his roots and his kindness.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-074', 'ar', 'كُنْ رَيَّقَ البِشْرِ إنْ الحُرَّ هِمَّتُهُ ... صَحيفَةٌ وعَلَيها البِشْرُ عُنْوانُ', 'Keep a bright, cheerful face; a free man''s spirit is a page, and cheerfulness is its title.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-075', 'ar', 'ورافِقِ الرَّفْقَ في كُلَّ الأمورِ فلَمْ ... يندّمْ رَفيقٌ ولم يذمُمْهُ إنسانُ', 'Be gentle in all matters; no gentle person regrets it, and no one blames him.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-076', 'ar', 'ولا يَغُرُّكَ حَظُّ جَرَّهْ خرقٌ ... فالخُرْقُ هَدمٌ ورِفقُ المَرءِ بُنْيانُ', 'Do not be fooled by luck that came from rashness; rashness tears down, and gentleness builds.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-077', 'ar', 'فلا تكُنْ عَجِلاً في الأمرِ تطلُبُهُ ... فليسَ يُحمَدُ قبل النُّضْجِ بُحْرانُ', 'Do not rush a thing you seek; nothing is praised before it ripens.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-078', 'ar', 'وللامُورِ مَواقيتٌ مُقَدَّرَةٌ ... وكُلُّ أمرٍ لهُ حَدُّ ومِيزانُ', 'Things have their appointed times, and every matter has its limit and its measure.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-079', 'ar', 'دَعِ التكاسُلَ في الخَيراتِ تطلُبُها ... فليسَ يسعَدُ بالخَيراتِ كَسْلانُ', 'Leave laziness when you seek good things, for the lazy never find happiness in them.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-080', 'ar', 'مَنْ يَزْرَعِ الشَّرَّ يَحصُدْ في عواقبِهِ ... نَدامَةً ولِحَصدِ الزَّرْعِ إبّانُ', 'Whoever plants evil harvests regret in the end, and every crop has its season.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-081', 'ar', 'أحسِنْ إذا كانَ إمكانٌ ومَقدِرهٌ ... فلن يَدومَ على الإنسانِ إمكانُ', 'Do good while you have the means and the power, for no one keeps that power forever.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-082', 'ar', 'حَسْبُ الفتى عقلُهُ خِلاًّ يُعاشِرُهُ ... إذا تحاماهُ إخوانٌ وخُلاّنُ', 'A man''s mind is enough of a companion when friends and comrades stay away.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-083', 'ar', 'إذا جَفاكَ خليلٌ كنتَ تألفُهُ ... فاطلُبْ سِواهُ فَكُلُّ النَّاسِ إخوانُ', 'If a friend you were close to turns cold, seek another, for all people are brothers.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-084', 'ar', 'مَنْ كانَ للخَيرِ مَنّاعاً فليسَ لَهُ ... على الحَقِيقَةِ إخوانٌ وأخْدانُ', 'Whoever withholds good has, in truth, no brothers or close friends.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-085', 'ar', 'يا أيُّها العَالِمُ المَرضِيُّ سيرَتُهُ ... أبشِرْ فأنتَ بغَيرِ الماءِ رَيانُ', 'O scholar whose conduct is praised, rejoice: you are satisfied without needing water.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-086', 'ar', 'مَنْ سالَمَ النّاسَ يسلَمْ من غوائِلِهمْ ... وعاشَ وَهْوَ قَريرُ العَينِ جَذْلانُ', 'Whoever is at peace with people is safe from their harm, and lives content and glad.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-087', 'ar', 'وذو القَناعَةِ راضٍ في مَعيشَتِهِ ... وصاحبُ الحِرْصِ إن أثرى فَغَضْبانُ', 'The contented man is satisfied with his living, and the greedy man, even when rich, is angry.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-088', 'ar', 'مَنْ كانَ للعَقلِ سُلطانٌ عَلَيهِ غَدا ... وما على نَفسِهِ للحِرْصِ سُلطانُ', 'Whoever is ruled by reason becomes one over whom greed has no power.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', '«النونية» (زيادة المرء في دنياه نقصان)', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/zyadh-almr-fy-dnyah-nqsan-w9n2n5oc', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-089', 'ar', 'سلِ اللهَ عَقلاً نافِعاً واستَعِذْ بهِ ... منَ الجَهلِ تَسأَلْ خَيرَ مُعْطٍ لِسائلِ', 'Ask God for useful understanding, and seek His protection from ignorance; you are asking the best giver.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', 'قصيدة «سل الله عقلا نافعا واستعذ به»', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/sl-allh-aqla-nafaa-wastadh-bh-twcp1mm9', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-abu-al-fath-al-busti-090', 'ar', 'فبالعَقلِ تُستوفى الفضائلُ كُلُّها ... كَما الجَهلُ مُستَوفٍ جميعَ الرَّذائلِ', 'With reason all virtues are gained, just as ignorance gathers all vices.', 'app', 'أبو الفتح البستي', 'Abu al-Fath al-Busti', 'قصيدة «سل الله عقلا نافعا واستعذ به»', 'القرن الرابع الهجري / 10th–11th century', 'https://adabworld.com/poems/sl-allh-aqla-nafaa-wastadh-bh-twcp1mm9', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّحت أخطاء طباعية ظاهرة في الصفحة.', '2026-11-03'),
('ar-al-imam-al-shafi-i-attri-091', 'ar', 'كُلَّما أَدَّبَني الدَهرُ أَراني نَقصَ عَقلي ... وَإِذا ما اِزدَدتُ عِلماً زادَني عِلماً بِجَهلي', 'Whenever time teaches me, it shows me the limits of my mind; the more I learn, the more I learn how little I know.', 'app', 'الإمام الشافعي (منسوب)', 'al-Imam al-Shafi''i (attributed)', '«كلما أدبني الدهر» — ديوان الشافعي', 'القرن الثاني الهجري / 8th–9th century', 'https://adabworld.com/poems/klma-adbny-aldh-vdodo6', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-al-mutanabbi-092', 'ar', 'ذو العَقلِ يَشقى في النَعيمِ بِعَقلِهِ ... وَأَخو الجَهالَةِ في الشَقاوَةِ يَنعَمُ', 'The wise man suffers in comfort because of his mind, and the ignorant man enjoys himself in misery.', 'app', 'المتنبي', 'al-Mutanabbi', '«لهوى النفوس سريرة لا تعلم»', 'القرن 10م / 10th century', 'https://adabworld.com/poems/lhwa-alnfws-sryra-la-iyb7gs', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-mutanabbi-094', 'ar', 'وَمِنَ العَداوَةِ ما يَنالُكَ نَفعُهُ ... وَمِنَ الصَداقَةِ ما يَضُرُّ وَيُؤلِمُ', 'Some enmity brings you benefit, and some friendship harms and hurts.', 'app', 'المتنبي', 'al-Mutanabbi', '«لهوى النفوس سريرة لا تعلم»', 'القرن 10م / 10th century', 'https://adabworld.com/poems/lhwa-alnfws-sryra-la-iyb7gs', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-al-mutanabbi-095', 'ar', 'وَمِنَ البَليَّةِ عَذلُ مَن لا يَرعَوي ... عَن غَيِّهِ وَخِطابُ مَن لا يَفهَمُ', 'It is an affliction to reproach someone who will not turn from his error, or to address someone who will not understand.', 'app', 'المتنبي', 'al-Mutanabbi', '«لهوى النفوس سريرة لا تعلم»', 'القرن 10م / 10th century', 'https://adabworld.com/poems/lhwa-alnfws-sryra-la-iyb7gs', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-hafez-ibrahim-096', 'ar', 'الأُمُّ مَدرَسَةٌ إِذا أَعدَدتَها ... أَعدَدتَ شَعباً طَيِّبَ الأَعراقِ', 'A mother is a school: prepare her well and you prepare a people of fine character.', 'app', 'حافظ إبراهيم', 'Hafez Ibrahim', '«كم ذا يكابد عاشق ويلاقي» (الأم مدرسة)', '1910 تقريبًا / c. 1910', 'https://adabworld.com/poems/km-dha-ykabd-aashq-wylaqy-fmn1d322', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-hafez-ibrahim-097', 'ar', 'لا تَحسَبَنَّ العِلمَ يَنفَعُ وَحدَهُ ... ما لَم يُتَوَّج رَبُّهُ بِخَلاقِ', 'Do not think knowledge benefits on its own unless its owner is crowned with good character.', 'app', 'حافظ إبراهيم', 'Hafez Ibrahim', '«كم ذا يكابد عاشق ويلاقي» (الأم مدرسة)', '1910 تقريبًا / c. 1910', 'https://adabworld.com/poems/km-dha-ykabd-aashq-wylaqy-fmn1d322', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-hafez-ibrahim-098', 'ar', 'وَالعِلمُ إِن لَم تَكتَنِفهُ شَمائِلٌ ... تُعليهِ كانَ مَطِيَّةَ الإِخفاقِ', 'Knowledge that is not surrounded by good qualities to raise it becomes a vehicle for failure.', 'app', 'حافظ إبراهيم', 'Hafez Ibrahim', '«كم ذا يكابد عاشق ويلاقي» (الأم مدرسة)', '1910 تقريبًا / c. 1910', 'https://adabworld.com/poems/km-dha-ykabd-aashq-wylaqy-fmn1d322', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-hafez-ibrahim-099', 'ar', 'فَإِذا رُزِقتَ خَليقَةً مَحمودَةً ... فَقَدِ اِصطَفاكَ مُقَسِّمُ الأَرزاقِ', 'If you have been given a praiseworthy character, the divider of fortunes has chosen you.', 'app', 'حافظ إبراهيم', 'Hafez Ibrahim', '«كم ذا يكابد عاشق ويلاقي» (الأم مدرسة)', '1910 تقريبًا / c. 1910', 'https://adabworld.com/poems/km-dha-ykabd-aashq-wylaqy-fmn1d322', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-lahham-al-taghlib-100', 'ar', 'وَلَيسَ الفَتى كَما يَقولُ لِسانُهُ ... إِذا لَم يَكُن فِعلٌ مَعَ القَولِ يُوجَدُ', 'A young man is not what his tongue says, unless there is action alongside the words.', 'app', 'أبو اللحام التغلبي', 'Abu al-Lahham al-Taghlibi', '«أمرت وطولت التفكر خاليا»', 'جاهلي/مخضرم', 'https://adabworld.com/poems/amrt-watwlt-altfkr-khalya-zj7v0ten', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ali-ibn-abi-talib-attrib-101', 'ar', 'العِلمُ زَينٌ فَكُن لِلعِلمِ مُكتَسِباً ... وَكُن لَهُ طالِباً ما عِشتَ مُقتَبِسا', 'Knowledge is an adornment, so keep acquiring it, and remain a seeker of it as long as you live.', 'app', 'علي بن أبي طالب (منسوب)', 'Ali ibn Abi Talib (attributed)', '«العلم زين فكن للعلم مكتسبا»', 'القرن 7م / 7th century', 'https://www.aldiwan.net/poem30998.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). النسبة مشهورة وليست قطعية.', '2026-11-03'),
('ar-abu-al-ala-al-maarri-102', 'ar', 'لا تَفرَحَنَّ بِفَألٍ إِن سَمِعتَ بِهِ ... وَلا تَطَيَّر إِذا ما ناعِبٌ نَعَبا', 'Do not rejoice at a good omen you hear, and do not feel doomed when a crow caws.', 'app', 'أبو العلاء المعري', 'Abu al-Ala al-Maarri', '«لا تفرحن بفأل إن سمعت به»', 'القرن 11م / 11th century', 'https://adabworld.com/poems/la-tfrhn-bfal-in-dhs3u6', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-ala-al-maarri-103', 'ar', 'فَالخَطبُ أَفظَعُ مِن سَرّاءَ تَأمُلُها ... وَالأَمرُ أَيسَرُ مِن أَن تُضمِرَ الرُعُبا', 'Disaster is harsher than the joy you hope for, and the matter is easier than the fear you carry.', 'app', 'أبو العلاء المعري', 'Abu al-Ala al-Maarri', '«لا تفرحن بفأل إن سمعت به»', 'القرن 11م / 11th century', 'https://adabworld.com/poems/la-tfrhn-bfal-in-dhs3u6', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-ala-al-maarri-104', 'ar', 'إِذا تَفَكَّرتَ فِكراً لا يُمازِجُهُ ... فَسادُ عَقلٍ صَحيحٍ هانَ ما صَعُبا', 'When you think with a sound mind, free of corruption, what was hard becomes easy.', 'app', 'أبو العلاء المعري', 'Abu al-Ala al-Maarri', '«لا تفرحن بفأل إن سمعت به»', 'القرن 11م / 11th century', 'https://adabworld.com/poems/la-tfrhn-bfal-in-dhs3u6', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-ala-al-maarri-105', 'ar', 'إِذا رَأَيتُم كَريماً عِندَ غَيرِكُمُ ... فَأَكرِموهُ عَلى يُسرٍ وَإِنضابِ', 'If you see a noble person among others, honor him, in ease and in hardship.', 'app', 'أبو العلاء المعري', 'Abu al-Ala al-Maarri', '«إذا رأيتم كريما عند غيركم»', 'القرن 11م / 11th century', 'https://adabworld.com/poems/idha-raytm-kryma-and-ii8f0z', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-106', 'ar', 'أَلا إِنَّما الإِخوانُ عِندَ الحَقائِقِ ... وَلا خَيرَ في وُدِّ الصَديقِ المُماذِقِ', 'True brothers are known when things become real; there is no good in a friend whose love is diluted.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«ألا إنما الإخوان عند الحقائق»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/ala-inma-alikhwan-and-j0jpii', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-107', 'ar', 'لَعَمرُكَ ما شَيءٌ مِنَ العَيشِ كُلِّهِ ... أَقَرَّ لِعَيني مِن صَديقٍ مُوافِقِ', 'By your life, nothing in all of living is more pleasing to my eyes than a like-minded friend.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«ألا إنما الإخوان عند الحقائق»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/ala-inma-alikhwan-and-j0jpii', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-108', 'ar', 'صَفِيِّ مِنَ الإِخوانِ كُلُّ مُوافِقٍ ... صَبورٍ عَلى ما نابَ عِندَ الحَقائِقِ', 'My true friend is everyone like-minded, patient with what befalls when things become real.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«ألا إنما الإخوان عند الحقائق»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/ala-inma-alikhwan-and-j0jpii', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-109', 'ar', 'وَلا خَيرَ فيمَن لا يُوَطِّنُ نَفسَهُ ... عَلى نائِباتِ الدَهرِ حينَ تَنوبُ', 'There is no good in one who does not prepare himself for the blows of time when they come.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«ولا خير فيمن لا يوطن نفسه»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/wla-khyr-fymn-la-z3jrqk', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-110', 'ar', 'طوبى لِكُلِّ مُفَكِّرٍ ... وَلِكُلِّ مُحتَسِبٍ صَبورِ', 'Blessed is everyone who reflects, and everyone who is patient and seeks reward.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«لله عاقبة الأمور»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/llh-aaqba-alamwr-rs62yd', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-111', 'ar', 'الصِدقُ شَيءٌ لا يَقومُ بِهِ اِمرُؤٌ ... إِلّا وَحَشوُ فُؤادِهِ الإيمانُ', 'Truthfulness is something no one can sustain unless his heart is filled with faith.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«كل امرئ فكما يدين يدان»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/kl-amr-fkma-ydyn-ni9tjk', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-112', 'ar', 'أَبشِر بِعَونِ اللَهِ إِن تَكُ مُحسِناً ... فَالمَرءُ يُحسِنُ طَرفَةً فَيُعانُ', 'Take heart in God''s help if you do good; a person does good for a moment and is helped.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«كل امرئ فكما يدين يدان»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/kl-amr-fkma-ydyn-ni9tjk', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-113', 'ar', 'أَلا إِنَّ أَبقى الذُخرِ خَيرٌ تُنيلُهُ ... وَشَرَّ كَلامِ القائِلينَ فُضولُهُ', 'The most lasting treasure is a good deed you give, and the worst speech is idle excess.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«ألا إن أبقى الذخر خير تنيله»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/ala-in-abqa-aldhkhr-20cori', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-114', 'ar', 'عَلَيكَ بِما يَعنيكَ مِن كُلِّ ما تَرى ... وَبِالصَمتِ إِلّا عَن جَميلٍ تَقولُهُ', 'Stick to what concerns you in all you see, and keep silent except for good words you say.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«ألا إن أبقى الذخر خير تنيله»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/ala-in-abqa-aldhkhr-20cori', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-115', 'ar', 'لا يُعجِبَنَّكَ يا ذا حُسنُ مَنظَرَةِ ... لَم يَجعَلِ اللَهُ فيها حُسنَ مَخبَرَةِ', 'Do not be impressed by a fine appearance that has no fine substance inside.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«لا يعجبنك يا ذا حسن منظرة»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/la-yajbnk-ya-dha-d82tk3', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-116', 'ar', 'خَيرُ اِكتِسابِ الفَتى ما كانَ مِن عَمَلٍ ... زاكٍ وَصَبرٍ عَلى عُسرٍ وَمَيسَرَةِ', 'The best a man can earn is pure action, and patience in hardship and in ease.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«لا يعجبنك يا ذا حسن منظرة»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/la-yajbnk-ya-dha-d82tk3', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-117', 'ar', 'وَأَفضَلُ الزُهدِ زُهدٌ كانَ عَن جِدَةٍ ... وَأَفضَلُ العَفوِ عَفوٌ عِندَ مَقدِرَةِ', 'The best renunciation is by one who has plenty, and the best forgiveness is by one who has power.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«لا يعجبنك يا ذا حسن منظرة»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/la-yajbnk-ya-dha-d82tk3', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-atahiya-118', 'ar', 'لا خَيرَ لا خَيرَ لِلإِنسانِ في طَمَعٍ ... يَصيرُ مِنهُ إِلى ذُلٍّ وَمَحقَرَةِ', 'No good, no good at all, for a person in greed that leads him to humiliation and contempt.', 'app', 'أبو العتاهية', 'Abu al-Atahiya', '«لا يعجبنك يا ذا حسن منظرة»', 'القرن 8–9م / 8th–9th century', 'https://adabworld.com/poems/la-yajbnk-ya-dha-d82tk3', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-al-ala-al-maarri-119', 'ar', 'إِسمَع مَقالَةَ ذي لُبٍّ وَتَجرُبَةٍ ... يُفِدكَ في اليَومِ ما في دَهرِهِ عَلِما', 'Listen to the words of a person of wisdom and experience; in a day he will give you what he learned in a lifetime.', 'app', 'أبو العلاء المعري', 'Abu al-Ala al-Maarri', '«إسمع مقالة ذي لب وتجربة»', 'القرن 11م / 11th century', 'https://adabworld.com/poems/isma-mqala-dhy-lb-a7ydgm', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-firas-al-hamdani-120', 'ar', 'تَهونُ عَلَينا في المَعالي نُفوسُنا ... وَمَن خَطَبَ الحَسناءَ لَم يُغلِها المَهرُ', 'Our lives are a small price to us in pursuit of the heights; whoever courts a beauty does not find the dowry too high.', 'app', 'أبو فراس الحمداني', 'Abu Firas al-Hamdani', '«أراك عصي الدمع شيمتك الصبر»', 'القرن 10م / 10th century', 'https://adabworld.com/poems/arak-asy-aldma-shymtk-vlpbft', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-firas-al-hamdani-122', 'ar', 'وَإِن مُتُّ فَالإِنسانُ لابُدَّ مَيِّتٌ ... وَإِن طالَتِ الأَيّامُ وَاِنفَسَحَ العُمرُ', 'If I die, every human must die, however long the days and wide the lifespan.', 'app', 'أبو فراس الحمداني', 'Abu Firas al-Hamdani', '«أراك عصي الدمع شيمتك الصبر»', 'القرن 10م / 10th century', 'https://adabworld.com/poems/arak-asy-aldma-shymtk-vlpbft', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ahmad-shawqi-123', 'ar', 'وإنما الأمم الأخلاق ما بقيت ... فإن همو ذهبت أخلاقهم ذهبوا', 'Nations live as long as their morals live; if their morals go, they go.', 'app', 'أحمد شوقي', 'Ahmad Shawqi', '«صحوت واستدركتني شيمتي الأدب»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/shwt-wastdrktny-shymty-aladb-n71fswxt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-ahmad-shawqi-124', 'ar', 'والصدق أرفع ما اهتز الرجال له ... وخير ما عوّد ابناً في الحياة أب', 'Truthfulness is the noblest thing that stirs men, and the best habit a father can give his son in life.', 'app', 'أحمد شوقي', 'Ahmad Shawqi', '«صحوت واستدركتني شيمتي الأدب»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/shwt-wastdrktny-shymty-aladb-n71fswxt', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). صُحّح «أبناً» إلى «ابناً».', '2026-11-03'),
('ar-abu-al-ala-al-maarri-125', 'ar', 'وَإِنَّ سَبيلَ الخَيرِ لِلمَرءِ واضِحٌ ... إِلى يَومٍ يَقضي ثُمَّ تَنقَطِعُ السُبُل', 'The path of good is clear for a person until the day he dies; then all paths are cut off.', 'app', 'أبو العلاء المعري', 'Abu al-Ala al-Maarri', '«إذا شئت أن ترقى جدارك مرة»', 'القرن 11م / 11th century', 'https://adabworld.com/poems/idha-sht-an-trqa-56mqer', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-abu-tammam-126', 'ar', 'السيف أصدق إنباءً من الكتب ... في حده الحد بين الجد واللعب', 'The sword is more truthful than books; its edge is the line between seriousness and play.', 'app', 'أبو تمام', 'Abu Tammam', '«السيف أصدق أنباءً من الكتب» (فتح عمورية)', '838م / 838 CE', 'https://diwanalarab.com/%d8%a7%d9%84%d8%b3%d9%8a%d9%81-%d8%a3%d8%b5%d8%af%d9%82-%d8%a5%d9%86%d8%a8%d8%a7%d8%a1%d9%8b', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-salih-ibn-abd-al-quddus-127', 'ar', 'أَطل الصَمت فَإِن الصَمتَ حلم ... وَإِذا قُمتَ فَبِالحَقِّ فَقُم', 'Keep long silences, for silence is wisdom; and when you stand up, stand up for what is right.', 'app', 'صالح بن عبد القدوس', 'Salih ibn Abd al-Quddus', '«أطل الصمت فإن الصمت حلم»', 'القرن 8م / 8th century', 'https://www.aldiwan.net/poem76223.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-salih-ibn-abd-al-quddus-128', 'ar', 'اِذا ما أَهَنت النَفسَ لَم تَلقَ مُكرماً ... لَها بَعد اِذ عَرضتها لهوان', 'If you humiliate yourself, you will find no one to honor you once you have exposed yourself to disgrace.', 'app', 'صالح بن عبد القدوس', 'Salih ibn Abd al-Quddus', '«اذا ما أهنت النفس لم تلق مكرما»', 'القرن 8م / 8th century', 'https://www.aldiwan.net/poem76215.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-salih-ibn-abd-al-quddus-129', 'ar', 'وَلا أَدرك الحاجاتِ مِثلُ مثابِر ... وَلا عاف عَنها النَجح مِثل ثَوان', 'Nothing achieves goals like persistence, and nothing keeps success away like slackness.', 'app', 'صالح بن عبد القدوس', 'Salih ibn Abd al-Quddus', '«اذا ما أهنت النفس لم تلق مكرما»', 'القرن 8م / 8th century', 'https://www.aldiwan.net/poem76215.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-salih-ibn-abd-al-quddus-130', 'ar', 'وَإِذا أَعلَنت أَمراً حسناً ... فَليَكُن أَحسَن مِنهُ ما تَسر', 'If you show something good in public, let what you keep in private be better still.', 'app', 'صالح بن عبد القدوس', 'Salih ibn Abd al-Quddus', '«وإذا أعلنت أمرا حسنا»', 'القرن 8م / 8th century', 'https://www.aldiwan.net/poem76224.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-maruf-al-rusafi-131', 'ar', 'أخْصِ في العلم إن أردت كمالاً ... ووصولاً إلى الفَخار الأتمّ', 'Specialize in knowledge if you want perfection and to reach the fullest pride.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«أخص في العلم إن أردت كمالا»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/akhs-fy-alalm-in-ardt-kmala-70bnang7', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-132', 'ar', 'وتَرَفّقْ إذا جهدت فإن الرفق ... يُذكي الفؤاد والعُنف يُعمي', 'Be gentle when you strive, for gentleness sharpens the mind and harshness blinds it.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«أخص في العلم إن أردت كمالا»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/akhs-fy-alalm-in-ardt-kmala-70bnang7', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-133', 'ar', 'وإذا ما اشتغلت بالجِدّ ساعات ... فهازل سُويعةً واستجم', 'When you have worked seriously for hours, play for a little while and rest.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«أخص في العلم إن أردت كمالا»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/akhs-fy-alalm-in-ardt-kmala-70bnang7', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-134', 'ar', 'كفى بالعلم في الظلمات نورا ... يُبيّن في الحياة لنا الأمورا', 'Knowledge is light enough in the darkness, making things clear for us in life.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«كفى بالعلم في الظلمات نورا»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/kfa-balalm-fy-alzlmat-nwra-k6ors1ap', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-135', 'ar', 'ولكن ليس مُنتَفِعاً بعلم ... فتىً لم يُحرز الخُلُق النضيرا', 'But a young man who has not gained fine character does not benefit from knowledge.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«كفى بالعلم في الظلمات نورا»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/kfa-balalm-fy-alzlmat-nwra-k6ors1ap', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-136', 'ar', 'إذا ما العلم لابس حُسنَ خُلْق ... فَرَجِّ لأهله خيراً كثيرا', 'When knowledge is clothed in good character, expect much good for those who have it.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«كفى بالعلم في الظلمات نورا»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/kfa-balalm-fy-alzlmat-nwra-k6ors1ap', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-137', 'ar', 'وما أن فاز أغزرنا علوماً ... ولكن فاز أسلمنا ضميرا', 'It is not the most learned of us who win, but the one with the soundest conscience.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«كفى بالعلم في الظلمات نورا»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/kfa-balalm-fy-alzlmat-nwra-k6ors1ap', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-salih-ibn-abd-al-quddus-139', 'ar', 'شَر المَواهِب ما تَجودُ بِهِ ... مِن غَيرِ محمدة وَلا أَجر', 'The worst gift is one given without praise or reward.', 'app', 'صالح بن عبد القدوس', 'Salih ibn Abd al-Quddus', '«شر المواهب ما تجود به»', 'القرن 8م / 8th century', 'https://www.aldiwan.net/poem76233.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-salih-ibn-abd-al-quddus-140', 'ar', 'وَنَفيتُ بِالياسِ المُنى ... عَنّي فَطابَ لي القَليلُ', 'I banished wishful longings with acceptance, and a little became enough for me.', 'app', 'صالح بن عبد القدوس', 'Salih ibn Abd al-Quddus', '«لله أحمد شاكرا»', 'القرن 8م / 8th century', 'https://www.aldiwan.net/poem76268.html', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر).', '2026-11-03'),
('ar-maruf-al-rusafi-141', 'ar', 'أدب العلم وعلم الأدب ... شرف النفس ونفس الشرف', 'The manners of learning and the learning of manners are the honor of the soul and the soul of honor.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«أدب العلم وعلم الأدب»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/adb-alalm-walm-aladb-v77n005l', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-142', 'ar', 'فالمعالي أودعت في الكتب ... كاللآلي أودعت في الصَدَف', 'High achievements are stored in books, as pearls are stored in shells.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«أدب العلم وعلم الأدب»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/adb-alalm-walm-aladb-v77n005l', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-143', 'ar', 'أوَ ما تعلم في هذي الحياة ... أن رب العلم حيٌّ لا يموت', 'Do you not know in this life that the person of knowledge lives on and never dies?', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«أدب العلم وعلم الأدب»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/adb-alalm-walm-aladb-v77n005l', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-144', 'ar', 'تَيَقّظ فما أنت بالخالد ... ولا حادث الدهر بالراقد', 'Wake up: you will not live forever, and the events of time do not sleep.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«تيقظ فما أنت بالخالد»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/tyqz-fma-ant-balkhald-sqekn45x', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-145', 'ar', 'فخلّد بسعيك مجداً يدوم ... دوام النجوم بلا جاحد', 'Immortalize yourself with effort, a glory that lasts like the stars, beyond denial.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«تيقظ فما أنت بالخالد»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/tyqz-fma-ant-balkhald-sqekn45x', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-146', 'ar', 'وأبقِ لك الذكر بالصالحات ... وخلّ النُزوع إلى الفاسد', 'Leave a good name through good deeds, and give up the pull toward what is corrupt.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«تيقظ فما أنت بالخالد»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/tyqz-fma-ant-balkhald-sqekn45x', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-147', 'ar', 'إذا هو أصبح نادى البدار ... وشَمَّر للسعي عن ساعد', 'When he wakes in the morning he calls out ''hurry!'' and rolls up his sleeves to work.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«تيقظ فما أنت بالخالد»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/tyqz-fma-ant-balkhald-sqekn45x', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('ar-maruf-al-rusafi-148', 'ar', 'ولا تكُ مُرمىً بداء السكون ... فتُصبحَ كالحجر الجامد', 'Do not be struck by the disease of stillness, or you will become like a lifeless stone.', 'app', 'معروف الرصافي', 'Maruf al-Rusafi', '«تيقظ فما أنت بالخالد»', 'أوائل القرن 20 / early 20th century', 'https://adabworld.com/poems/tyqz-fma-ant-balkhald-sqekn45x', 'ملكية عامة؛ النص منقول من الصفحة المرتبطة كما هو (التشكيل من المصدر). تقسيم الشطرين أو وصل كلمة مقطوعة في الصفحة تمّ منّا.', '2026-11-03'),
('en--000', 'en', 'Since it is possible that thou mayest depart from life this very moment, regulate every act and thought accordingly.', 'بما أنك قد تغادر الحياة في هذه اللحظة، فاضبط كل فعل وكل فكرة على هذا الأساس.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--001', 'en', 'Give thyself time to learn something new and good, and cease to be whirled around.', 'امنح نفسك وقتًا لتتعلم شيئًا جديدًا ونافعًا، وكُفَّ عن الدوران في كل اتجاه.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--002', 'en', 'A man then must stand erect, not be kept erect by others.', 'على الإنسان أن يقف منتصبًا بنفسه، لا أن يُسنِده الآخرون.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--003', 'en', 'Let no act be done without a purpose, nor otherwise than according to the perfect principles of art.', 'لا تفعل شيئًا بلا غاية، ولا على غير أصول الإتقان.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--004', 'en', 'Take away thy opinion, and then there is taken away the complaint, "I have been harmed."', 'أزِل رأيك في الأمر، يزُل معه الشعور بأنك «تضرّرت».', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--005', 'en', 'Do not act as if thou wert going to live ten thousand years.', 'لا تتصرف كأنك ستعيش عشرة آلاف سنة.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--006', 'en', 'While thou livest, while it is in thy power, be good.', 'ما دمت حيًّا، وما دام الأمر في يدك، فكن صالحًا.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--007', 'en', 'Thou must turn to profit the present by the aid of reason and justice.', 'عليك أن تنتفع بالحاضر بالعقل والعدل.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--008', 'en', 'I am rising to the work of a human being.', 'أنا أنهض لأؤدي عمل الإنسان.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--009', 'en', 'Nothing happens to any man which he is not formed by nature to bear.', 'لا يصيب الإنسانَ شيءٌ إلا وقد هيّأته طبيعته لاحتماله.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--010', 'en', 'The best way of avenging thyself is not to become like the wrong doer.', 'أفضل طريقة للانتقام ألّا تصير مثل المسيء.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--011', 'en', 'Be not ashamed to be helped; for it is thy business to do thy duty like a soldier in the assault on a town.', 'لا تخجل من طلب العون؛ فواجبك أن تؤدي مهمتك كجندي يقتحم حصنًا.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--013', 'en', 'In discourse thou must attend to what is said, and in every movement thou must observe what is doing.', 'في الحديث أصغِ لما يُقال، وفي كل حركة انتبه لما يجري.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--014', 'en', 'I can have that opinion about anything, which I ought to have.', 'أستطيع أن أتبنى في أي أمر الرأيَ الذي ينبغي أن أتبناه.', 'app', 'Marcus Aurelius', 'ماركوس أوريليوس', 'Meditations, tr. George Long', 'c. 170 CE (tr. 1862)', 'https://classics.mit.edu/Antoninus/meditations.mb.txt', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--015', 'en', 'Some things are in our control and others not.', 'بعض الأشياء في نطاق سيطرتنا، وبعضها ليس كذلك.', 'app', 'Epictetus', 'إبكتيتوس', 'Enchiridion, tr. Elizabeth Carter', 'c. 125 CE (tr. 1758)', 'https://classics.mit.edu/Epictetus/epicench.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--016', 'en', 'Men are disturbed, not by things, but by the principles and notions which they form concerning things.', 'لا تُقلق الناسَ الأشياءُ نفسها، بل الأفكار والتصورات التي يكوّنونها عنها.', 'app', 'Epictetus', 'إبكتيتوس', 'Enchiridion, tr. Elizabeth Carter', 'c. 125 CE (tr. 1758)', 'https://classics.mit.edu/Epictetus/epicench.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--017', 'en', 'Don''t demand that things happen as you wish, but wish that they happen as they do happen, and you will go on well.', 'لا تطلب أن تجري الأمور كما تريد، بل أرِد أن تجري كما تجري، فتسير أمورك على خير.', 'app', 'Epictetus', 'إبكتيتوس', 'Enchiridion, tr. Elizabeth Carter', 'c. 125 CE (tr. 1758)', 'https://classics.mit.edu/Epictetus/epicench.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--018', 'en', 'With every accident, ask yourself what abilities you have for making a proper use of it.', 'مع كل طارئ، اسأل نفسك: ما القدرات التي أملكها لأحسن التعامل معه؟', 'app', 'Epictetus', 'إبكتيتوس', 'Enchiridion, tr. Elizabeth Carter', 'c. 125 CE (tr. 1758)', 'https://classics.mit.edu/Epictetus/epicench.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--019', 'en', 'If you want to improve, be content to be thought foolish and stupid with regard to external things.', 'إن أردت أن تتقدم، فارضَ أن تُعدّ ساذجًا في نظر الناس فيما يخص المظاهر الخارجية.', 'app', 'Epictetus', 'إبكتيتوس', 'Enchiridion, tr. Elizabeth Carter', 'c. 125 CE (tr. 1758)', 'https://classics.mit.edu/Epictetus/epicench.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--020', 'en', 'In every affair consider what precedes and follows, and then undertake it.', 'في كل أمر، تأمّل ما يسبقه وما يتبعه، ثم أقدِم عليه.', 'app', 'Epictetus', 'إبكتيتوس', 'Enchiridion, tr. Elizabeth Carter', 'c. 125 CE (tr. 1758)', 'https://classics.mit.edu/Epictetus/epicench.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--021', 'en', 'Never call yourself a philosopher, nor talk a great deal among the unlearned about theorems, but act conformably to them.', 'لا تسمِّ نفسك فيلسوفًا، ولا تُكثر الكلام عن النظريات، بل اعمل بمقتضاها.', 'app', 'Epictetus', 'إبكتيتوس', 'Enchiridion, tr. Elizabeth Carter', 'c. 125 CE (tr. 1758)', 'https://classics.mit.edu/Epictetus/epicench.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--022', 'en', 'Let whatever appears to be the best be to you an inviolable law.', 'ليكن ما يبدو لك الأفضلَ قانونًا لا يُخرق.', 'app', 'Epictetus', 'إبكتيتوس', 'Enchiridion, tr. Elizabeth Carter', 'c. 125 CE (tr. 1758)', 'https://classics.mit.edu/Epictetus/epicench.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--023', 'en', 'You see where the true happiness lies, but you have not the courage to attain it.', 'أنت ترى أين تكمن السعادة الحقيقية، لكنك لا تملك الشجاعة لبلوغها.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--024', 'en', 'You are better at approving the right course than at following it out.', 'أنت أبرع في استحسان الطريق الصحيح منك في السير فيه.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--025', 'en', 'We should toughen our minds, and remove them far from the allurements of pleasure.', 'ينبغي أن نقوّي عقولنا ونبعدها عن إغراءات اللذة.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--026', 'en', 'Perspiration should flow only after toil.', 'لا ينبغي أن يسيل العرق إلا بعد الكدّ.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--028', 'en', 'We can get assistance not only from the living, but from those of the past.', 'يمكننا أن نستعين لا بالأحياء فقط، بل بمن سبقونا أيضًا.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--029', 'en', 'Choose as a guide one whom you will admire more when you see him act than when you hear him speak.', 'اختر مرشدًا تزداد إعجابًا به حين تراه يعمل أكثر مما تسمعه يتكلم.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--030', 'en', 'Do not study philosophy merely during your spare time.', 'لا تدرس الفلسفة في أوقات فراغك فقط.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--031', 'en', 'Philosophy wields her own authority; she appoints her own time and does not allow it to be appointed for her.', 'للفلسفة سلطانها الخاص؛ هي تحدد وقتها ولا تسمح لأحد أن يحدده لها.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--032', 'en', 'A friend should be retained in the spirit; such a friend can never be absent.', 'الصديق يُحفظ في الروح، ومثل هذا الصديق لا يغيب أبدًا.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--033', 'en', 'So true it is that fear looks not to the effect, but to the cause of the effect.', 'إن الخوف لا ينظر إلى الأثر، بل إلى سبب الأثر.', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--034', 'en', 'Will you not stop fearing lest that may happen once which really happens every day?', 'ألا تكفّ عن الخوف من أن يقع مرةً ما يقع في الحقيقة كل يوم؟', 'app', 'Seneca', 'سينيكا', 'Moral Letters to Lucilius, tr. Richard M. Gummere', 'c. 65 CE (tr. 1917–25)', 'https://topostext.org/work/736', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--036', 'en', 'Sloth, like Rust, consumes faster than Labour wears, while the used Key is always bright', 'الكسل كالصدأ، يأكل أسرع مما يُبلي العمل، والمفتاح المستعمل لامع دائمًا.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--037', 'en', 'dost thou love Life, then do not squander Time, for that’s the Stuff Life is made of', 'أتحب الحياة؟ إذن لا تبدّد الوقت، فهو المادة التي صُنعت منها الحياة.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--038', 'en', 'The sleeping Fox catches no Poultry', 'الثعلب النائم لا يصطاد دجاجًا.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--039', 'en', 'Lost Time is never found again', 'الوقت الضائع لا يُستعاد أبدًا.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--040', 'en', 'Sloth makes all Things difficult, but Industry all easy', 'الكسل يجعل كل شيء صعبًا، والاجتهاد يجعل كل شيء سهلًا.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--041', 'en', 'He that riseth late, must trot all Day, and shall scarce overtake his Business at Night', 'من يستيقظ متأخرًا يظل يركض طوال اليوم، وبالكاد يدرك عمله في الليل.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--042', 'en', 'Laziness travels so slowly, that Poverty soon overtakes him', 'الكسل يمشي ببطء شديد حتى يلحق به الفقر سريعًا.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--043', 'en', 'Drive thy Business, let not that drive thee', 'قُد عملك، ولا تدعه يقودك.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--044', 'en', 'Early to Bed, and early to rise, makes a Man healthy, wealthy and wise', 'النوم مبكرًا والاستيقاظ مبكرًا يجعلان المرء صحيحًا وغنيًا وحكيمًا.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--045', 'en', 'Industry need not wish', 'المجتهد لا يحتاج إلى التمنّي.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--046', 'en', 'He that lives upon Hope will die fasting', 'من يعيش على الأمل وحده يموت جائعًا.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--047', 'en', 'There are no Gains, without Pains', 'لا مكاسب بلا تعب.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--048', 'en', 'He that hath a Trade hath an Estate', 'من يملك حرفة يملك ثروة.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--049', 'en', 'Diligence is the Mother of Good luck', 'الاجتهاد أبو الحظ السعيد.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--050', 'en', 'One To-day is worth two Tomorrows', 'يوم واحد اليوم خير من غدَين.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--051', 'en', 'Have you somewhat to do To-morrow, do it To-day', 'إن كان لديك عمل غدًا، فأنجزه اليوم.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--052', 'en', 'constant Dropping wears away Stones', 'قطرات الماء المتتابعة تثقب الحجر.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--053', 'en', 'little Strokes fell great Oaks', 'الضربات الصغيرة تُسقط أشجار البلوط العظيمة.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--054', 'en', 'Employ thy Time well if thou meanest to gain Leisure', 'أحسِن استغلال وقتك إن أردت أن تنال الراحة.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--055', 'en', 'since thou art not sure of a Minute, throw not away an Hour', 'ما دمت لست متأكدًا من دقيقة، فلا تُضيّع ساعة.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--056', 'en', 'Keep thy Shop, and thy Shop will keep thee', 'اعتنِ بمتجرك، يعتنِ بك متجرك.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--057', 'en', 'The Eye of a Master will do more Work than both his Hands', 'عين صاحب العمل تُنجز أكثر مما تنجزه يداه.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--058', 'en', 'If you would be wealthy, think of Saving as well as of Getting', 'إن أردت الثراء، ففكّر في الادخار كما تفكر في الكسب.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'The Way to Wealth', '1757', 'https://teachingamericanhistory.org/document/the-way-to-wealth/', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--059', 'en', 'Temperance. Eat not to dullness; drink not to elevation.', 'الاعتدال: لا تأكل حتى الخمول، ولا تشرب حتى السُّكر.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--060', 'en', 'Silence. Speak not but what may benefit others or yourself; avoid trifling conversation.', 'الصمت: لا تقل إلا ما ينفع غيرك أو ينفعك، وتجنّب الكلام التافه.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--061', 'en', 'Order. Let all your things have their places; let each part of your business have its time.', 'النظام: اجعل لكل شيء من أشيائك مكانًا، ولكل جزء من عملك وقتًا.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--062', 'en', 'Resolution. Resolve to perform what you ought; perform without fail what you resolve.', 'العزم: اعزم على أداء ما يجب عليك، وأدِّ ما عزمت عليه دون تقصير.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--063', 'en', 'Frugality. Make no expense but to do good to others or yourself, i.e., waste nothing.', 'الاقتصاد: لا تنفق إلا لخيرٍ لغيرك أو لنفسك؛ أي لا تُسرف في شيء.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--064', 'en', 'Industry. Lose no time; be always employed in something useful; cut off all unnecessary actions.', 'الاجتهاد: لا تُضِع وقتًا؛ كن دائمًا مشغولًا بشيء نافع، واقطع كل عمل لا ضرورة له.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--065', 'en', 'Sincerity. Use no hurtful deceit; think innocently and justly, and, if you speak, speak accordingly.', 'الصدق: لا تلجأ إلى خداع مؤذٍ؛ فكّر ببراءة وعدل، وإن تكلمت فتكلم بما يوافق ذلك.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--066', 'en', 'Justice. Wrong none by doing injuries or omitting the benefits that are your duty.', 'العدل: لا تظلم أحدًا بإيذائه، أو بإغفال ما يجب عليك من نفعه.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--067', 'en', 'Moderation. Avoid extremes; forbear resenting injuries so much as you think they deserve.', 'التوسط: تجنّب التطرف، ولا تُبالغ في الغضب من الإساءة بقدر ما تظن أنها تستحق.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--068', 'en', 'Cleanliness. Tolerate no uncleanliness in body, clothes, or habitation.', 'النظافة: لا تقبل أي قذارة في جسدك أو ثيابك أو مسكنك.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--069', 'en', 'Tranquillity. Be not disturbed at trifles, or at accidents common or unavoidable.', 'السكينة: لا تضطرب للتوافه، ولا للحوادث المعتادة أو التي لا مفر منها.', 'app', 'Benjamin Franklin', 'بنجامين فرانكلين', 'Autobiography — the thirteen virtues', '1791', 'https://ushistory.org/FRANKLIN/autobiography/page38.htm', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Virtue name added before its precept as on the page.', '2026-11-03'),
('en--070', 'en', 'I went to the woods because I wished to live deliberately, to front only the essential facts of life, and see if I could not learn what it had to teach.', 'ذهبت إلى الغابة لأني أردت أن أعيش بوعي، وأواجه حقائق الحياة الأساسية فقط، وأرى إن كنت أستطيع أن أتعلم ما لديها لتعلّمني إياه.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 2 “Where I Lived, and What I Lived For”', '1854', 'https://etc.usf.edu/lit2go/90/walden-or-life-in-the-woods/1538/where-i-lived-and-what-i-lived-for', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--071', 'en', 'Our life is frittered away by detail.', 'حياتنا تتبدد في التفاصيل.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 2 “Where I Lived, and What I Lived For”', '1854', 'https://etc.usf.edu/lit2go/90/walden-or-life-in-the-woods/1538/where-i-lived-and-what-i-lived-for', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--072', 'en', 'Let us spend one day as deliberately as Nature, and not be thrown off the track by every nutshell and mosquito''s wing that falls on the rails.', 'لنقضِ يومًا واحدًا بتأنٍّ مثل الطبيعة، دون أن تُخرجنا عن مسارنا قشرةُ جوزة أو جناح بعوضة يسقط على السكة.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 2 “Where I Lived, and What I Lived For”', '1854', 'https://etc.usf.edu/lit2go/90/walden-or-life-in-the-woods/1538/where-i-lived-and-what-i-lived-for', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--073', 'en', 'Time is but the stream I go a-fishing in.', 'ما الوقت إلا نهر أذهب لأصطاد فيه.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 2 “Where I Lived, and What I Lived For”', '1854', 'https://etc.usf.edu/lit2go/90/walden-or-life-in-the-woods/1538/where-i-lived-and-what-i-lived-for', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page. Dash normalized from the page.', '2026-11-03'),
('en--074', 'en', 'Morning is when I am awake and there is a dawn in me.', 'الصباح هو حين أكون يقظًا ويكون في داخلي فجر.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 2 “Where I Lived, and What I Lived For”', '1854', 'https://etc.usf.edu/lit2go/90/walden-or-life-in-the-woods/1538/where-i-lived-and-what-i-lived-for', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--075', 'en', 'To be awake is to be alive.', 'أن تكون يقظًا يعني أن تكون حيًّا.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 2 “Where I Lived, and What I Lived For”', '1854', 'https://etc.usf.edu/lit2go/90/walden-or-life-in-the-woods/1538/where-i-lived-and-what-i-lived-for', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--076', 'en', 'Why should we live with such hurry and waste of life?', 'لماذا نعيش بكل هذه العجلة وهذا الهدر للحياة؟', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 2 “Where I Lived, and What I Lived For”', '1854', 'https://etc.usf.edu/lit2go/90/walden-or-life-in-the-woods/1538/where-i-lived-and-what-i-lived-for', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--077', 'en', 'Sell your clothes and keep your thoughts.', 'بِع ثيابك واحتفظ بأفكارك.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://human.libretexts.org/Bookshelves/Literature_and_Literacy/American_Literature/American_Literature_I_(Eidenmuller)/04:_Romantic_Literature_(18201860)/4.17:_Walden-_Conclusion', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--078', 'en', 'Things do not change; we change.', 'الأشياء لا تتغير؛ نحن الذين نتغير.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://human.libretexts.org/Bookshelves/Literature_and_Literacy/American_Literature/American_Literature_I_(Eidenmuller)/04:_Romantic_Literature_(18201860)/4.17:_Walden-_Conclusion', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--079', 'en', 'Do not trouble yourself much to get new things, whether clothes or friends.', 'لا تُتعب نفسك كثيرًا في الحصول على أشياء جديدة، سواء أكانت ثيابًا أم أصدقاء.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://human.libretexts.org/Bookshelves/Literature_and_Literacy/American_Literature/American_Literature_I_(Eidenmuller)/04:_Romantic_Literature_(18201860)/4.17:_Walden-_Conclusion', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--080', 'en', 'Let him step to the music which he hears, however measured or far away.', 'دعه يمشِ على إيقاع الموسيقى التي يسمعها، مهما كانت هادئة أو بعيدة.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://human.libretexts.org/Bookshelves/Literature_and_Literacy/American_Literature/American_Literature_I_(Eidenmuller)/04:_Romantic_Literature_(18201860)/4.17:_Walden-_Conclusion', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--081', 'en', 'Love your life, poor as it is.', 'أحِبَّ حياتك، مهما كانت فقيرة.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://human.libretexts.org/Bookshelves/Literature_and_Literacy/American_Literature/American_Literature_I_(Eidenmuller)/04:_Romantic_Literature_(18201860)/4.17:_Walden-_Conclusion', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--082', 'en', 'Let every one mind his own business, and endeavor to be what he was made.', 'ليهتمّ كلٌّ بشأنه، وليسعَ إلى أن يكون ما خُلق ليكونه.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://human.libretexts.org/Bookshelves/Literature_and_Literacy/American_Literature/American_Literature_I_(Eidenmuller)/04:_Romantic_Literature_(18201860)/4.17:_Walden-_Conclusion', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--083', 'en', 'Only that day dawns to which we are awake.', 'لا يطلع إلا ذلك اليوم الذي نكون له يقظين.', 'app', 'Henry David Thoreau', 'هنري ديفيد ثورو', 'Walden, ch. 18 “Conclusion”', '1854', 'https://human.libretexts.org/Bookshelves/Literature_and_Literacy/American_Literature/American_Literature_I_(Eidenmuller)/04:_Romantic_Literature_(18201860)/4.17:_Walden-_Conclusion', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--085', 'en', 'Absolve you to yourself, and you shall have the suffrage of the world.', 'برِّئ نفسك أمام نفسك، تنَل تأييد العالم.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--086', 'en', 'A foolish consistency is the hobgoblin of little minds, adored by little statesmen and philosophers and divines.', 'الاتساق الأحمق هو غول العقول الصغيرة، يعبده صغار الساسة والفلاسفة ورجال الدين.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--087', 'en', 'Whoso would be a man must be a nonconformist.', 'من أراد أن يكون رجلًا فعليه ألا يكون مقلِّدًا.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--088', 'en', 'Every great man is an unique.', 'كل عظيم فريد من نوعه.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--089', 'en', 'Do that which is assigned thee, and thou canst not hope too much or dare too much.', 'أدِّ ما أُسند إليك، ولن تكون مفرطًا في الأمل أو الجرأة.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--090', 'en', 'Do your work, and you shall reinforce yourself.', 'أنجز عملك، تَقْوَ بنفسك.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--091', 'en', 'We pass for what we are.', 'نحن نُعرَف بما نحن عليه حقًا.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--092', 'en', 'Your genuine action will explain itself and will explain your other genuine actions.', 'فعلك الصادق يشرح نفسه، ويشرح أفعالك الصادقة الأخرى.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--093', 'en', 'The force of character is cumulative.', 'قوة الشخصية تتراكم.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--094', 'en', 'Greatness always appeals to the future.', 'العظمة تخاطب المستقبل دائمًا.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--095', 'en', 'Be it how it will, do right now.', 'مهما يكن من أمر، افعل الصواب الآن.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--097', 'en', 'No law can be sacred to me but that of my nature.', 'لا قانون مقدّس عندي إلا قانون طبيعتي.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--099', 'en', 'Discontent is the want of self-reliance: it is infirmity of will.', 'السخط هو نقص الاعتماد على النفس؛ إنه ضعف في الإرادة.', 'app', 'Ralph Waldo Emerson', 'رالف والدو إمرسون', 'Self-Reliance', '1841', 'https://anthology.lib.virginia.edu/work/Emerson/emerson-self-reliance', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--100', 'en', 'Let us, then, be up and doing, / With a heart for any fate; / Still achieving, still pursuing, / Learn to labor and to wait.', 'فلننهض إذن ولنعمل، بقلب مستعد لأي قدر؛ نواصل الإنجاز والسعي، ونتعلم أن نكدّ وأن ننتظر.', 'app', 'Henry Wadsworth Longfellow', 'هنري وادزورث لونغفيلو', 'A Psalm of Life', '1838', 'https://www.poetryfoundation.org/poems/44644/a-psalm-of-life', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--101', 'en', 'Act,— act in the living Present! / Heart within, and God o’erhead!', 'اعمل، اعمل في الحاضر الحي! القلب في داخلك، والله فوقك!', 'app', 'Henry Wadsworth Longfellow', 'هنري وادزورث لونغفيلو', 'A Psalm of Life', '1838', 'https://www.poetryfoundation.org/poems/44644/a-psalm-of-life', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--102', 'en', 'Be not like dumb, driven cattle! / Be a hero in the strife!', 'لا تكن كالماشية الخرساء المسوقة! كن بطلًا في المعركة!', 'app', 'Henry Wadsworth Longfellow', 'هنري وادزورث لونغفيلو', 'A Psalm of Life', '1838', 'https://www.poetryfoundation.org/poems/44644/a-psalm-of-life', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--103', 'en', 'How dull it is to pause, to make an end, / To rust unburnish''d, not to shine in use!', 'ما أبلد أن تتوقف، أن تضع نهاية، أن تصدأ غير مصقول بدل أن تلمع في الاستعمال!', 'app', 'Alfred, Lord Tennyson', 'ألفريد تينيسون', 'Ulysses', '1842', 'https://rpo.library.utoronto.ca/poems/ulysses', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--104', 'en', 'To follow knowledge like a sinking star, / Beyond the utmost bound of human thought.', 'أن تتبع المعرفة كنجم يهوي، إلى ما وراء أقصى حدود الفكر البشري.', 'app', 'Alfred, Lord Tennyson', 'ألفريد تينيسون', 'Ulysses', '1842', 'https://rpo.library.utoronto.ca/poems/ulysses', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--105', 'en', 'Made weak by time and fate, but strong in will / To strive, to seek, to find, and not to yield.', 'أضعفنا الزمن والقدر، لكننا أقوياء الإرادة: أن نسعى، ونبحث، ونجد، ولا نستسلم.', 'app', 'Alfred, Lord Tennyson', 'ألفريد تينيسون', 'Ulysses', '1842', 'https://rpo.library.utoronto.ca/poems/ulysses', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--106', 'en', 'I am the master of my fate; / I am the captain of my soul.', 'أنا سيّد قدري، أنا قائد روحي.', 'app', 'William Ernest Henley', 'وليام إرنست هنلي', 'Invictus', '1888', 'https://www.poetryloverspage.com/poets/henley/invictus.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--107', 'en', 'Under the bludgeoning of chance / My head is bloody, but unbowed.', 'تحت ضربات الصدفة القاسية، رأسي دامٍ لكنه لا ينحني.', 'app', 'William Ernest Henley', 'وليام إرنست هنلي', 'Invictus', '1888', 'https://www.poetryloverspage.com/poets/henley/invictus.html', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--108', 'en', 'Is it not pleasant to learn with a constant perseverance and application?', 'أليس من الممتع أن تتعلم بمثابرة واجتهاد دائمين؟', 'app', 'Confucius', 'كونفوشيوس', 'Analects, Book 1, tr. James Legge', 'c. 5th century BCE (tr. 1861)', 'https://mail.yellowbridge.com/onlinelit/analects01.php', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03'),
('en--109', 'en', 'When you have faults, do not fear to abandon them.', 'إن كانت لديك أخطاء، فلا تخشَ أن تتخلى عنها.', 'app', 'Confucius', 'كونفوشيوس', 'Analects, Book 1, tr. James Legge', 'c. 5th century BCE (tr. 1861)', 'https://mail.yellowbridge.com/onlinelit/analects01.php', 'Public domain (author died long ago; translation pre-1929 where applicable). Copied from the linked page.', '2026-11-03')
